<div class="page-heading"><div><div class="eyebrow">Ruang pemohon</div><h1>Permohonan saya</h1><p>Pantau setiap UTTP dan unduh hasil yang sudah tersedia.</p></div><div class="registry-actions"><?php if ($current_user->account_type==='applicant' && $this->metro->can($current_user->id,'self.uttp.view')): ?><a class="button outline" href="<?= site_url('uttp') ?>">Daftar UTTP</a><?php endif; ?><?php if ($this->metro->can($current_user->id,'self.requests.create')): ?><a class="button primary" href="<?= site_url('permohonan/baru') ?>">+ Ajukan layanan</a><?php endif; ?></div></div>
<form class="card filter-card self-feed-filter" method="get" action="<?= site_url('permohonan') ?>" data-ajax-feed><label>Cari nomor order / UTTP<input type="search" name="q" value="<?= e($query) ?>" placeholder="Ketik untuk mencari"></label><label>Status<select name="status"><option value="">Semua status</option><?php foreach ($this->master->options('status',FALSE) as $option): ?><option value="<?= e($option->option_code) ?>"<?= $selected_status===$option->option_code?' selected':'' ?>><?= e($option->option_label) ?></option><?php endforeach; ?></select></label><label>Baris per halaman<select name="rows"><?php foreach (array(5,10,25) as $count): ?><option value="<?= $count ?>"<?= $rows===$count?' selected':'' ?>><?= $count ?></option><?php endforeach; ?></select></label><button class="button primary" type="submit">Tampilkan</button></form>
<div id="self-feed-results">
<section class="section" id="history-feed"><div class="section-heading"><h2>Riwayat permohonan</h2><span class="muted small"><?= (int)$pagination['total'] ?> permohonan</span></div><?php if (!$requests): ?><div class="card empty"><h3>Belum ada permohonan yang cocok</h3><p>Ubah pencarian atau ajukan layanan baru.</p></div><?php else: ?><div class="list-grid self-feed-scroll"><?php foreach ($requests as $r): ?><a class="card request-card" href="<?= site_url('permohonan/'.$r->id) ?>"><div class="request-top"><strong><?= e($r->request_no) ?></strong><span class="badge <?= status_class($r->request_status) ?>"><?= e(status_label($r->request_status)) ?></span></div><div class="request-bottom"><span><?= e(service_types_label($r->service_types ?: $r->service_type)) ?> · <?= (int)$r->unit_count ?> unit</span><span><?= e(tanggal_id($r->submitted_at)) ?> →</span></div></a><?php endforeach; ?></div><?php endif; ?><?= metro_pager($pagination,'permohonan',array('q'=>$query,'status'=>$selected_status,'rows'=>$rows,'news_page'=>$news_pagination['page'])) ?></section>
<section class="section" id="news-feed"><div class="section-heading"><h2>Kabar terbaru</h2><span class="muted small"><?= (int)$news_pagination['total'] ?> pembaruan</span></div><?php if (!$news): ?><div class="card empty"><h3>Belum ada kabar untuk filter ini</h3></div><?php else: ?><div class="self-feed-scroll news-feed-list"><?php foreach ($news as $entry): ?><a class="card news-feed-item" href="<?= site_url('permohonan/'.$entry->request_id) ?>"><div><strong><?= e($entry->request_no) ?> · UTTP <?= (int)$entry->unit_sequence ?> · <?= e($entry->uttp_name) ?></strong><span class="badge <?= status_class($entry->to_status) ?>"><?= e(status_label($entry->to_status)) ?></span></div><p><?= e(implode(' · ',array_filter(array($entry->brand,$entry->type_name,$entry->capacity,$entry->media?'Media '.$entry->media:NULL,$entry->nozzle_no?'Nozzle '.$entry->nozzle_no:NULL,$entry->dispenser_no?'Dispenser '.$entry->dispenser_no:NULL,$entry->manufacture_year?'Tahun '.$entry->manufacture_year:NULL,$entry->flow_rate?'Qmax/Qmin '.$entry->flow_rate:NULL,$entry->readability?'Daya baca '.$entry->readability:NULL)))) ?></p><small><?= e(tanggal_id($entry->created_at,TRUE)) ?><?= $entry->note?' · '.e($entry->note):'' ?></small></a><?php endforeach; ?></div><?php endif; ?><?= metro_pager($news_pagination,'permohonan',array('q'=>$query,'status'=>$selected_status,'rows'=>$rows,'page'=>$pagination['page']),'news_page') ?></section>
</div>
<script src="<?= base_url('assets/self-feed.js?v=1') ?>" defer></script>
